-- Migration additive : conserver les carnets, remises, notes et certificats existants.
begin;
create table if not exists public.academy_lessons (
 level integer not null check(level between 1 and 4), step integer not null,
 title text not null, first_page integer not null, last_page integer not null,
 primary key(level,step));
create table if not exists public.academy_requirements (
 id text primary key, level integer not null, step integer not null,
 kind text not null, title text not null, page integer not null, instruction text not null,
 foreign key(level,step) references public.academy_lessons(level,step));
create table if not exists public.academy_reading_pages (
 level integer not null, page integer not null, step integer not null,
 primary key(level,page), foreign key(level,step) references public.academy_lessons(level,step));
create table if not exists public.academy_read_receipts (
 user_id uuid not null references auth.users(id), level integer not null, page integer not null,
 acknowledged_at timestamptz not null default now(), primary key(user_id,level,page),
 foreign key(level,page) references public.academy_reading_pages(level,page));
create table if not exists public.academy_work (
 user_id uuid not null references auth.users(id), requirement_id text not null references public.academy_requirements(id),
 answer text not null check(length(trim(answer)) between 120 and 30000),
 state text not null default 'submitted' check(state in ('submitted','accepted','revision')),
 feedback text not null default '', reviewed_by uuid references auth.users(id), reviewed_at timestamptz,
 updated_at timestamptz not null default now(),primary key(user_id,requirement_id));
alter table public.academy_progress add column if not exists requirements_version integer not null default 1;
alter table public.academy_assessments add column if not exists evidence jsonb;
alter table public.academy_lessons enable row level security;
alter table public.academy_requirements enable row level security;
alter table public.academy_reading_pages enable row level security;
alter table public.academy_read_receipts enable row level security;
alter table public.academy_work enable row level security;
revoke all on public.academy_lessons,public.academy_requirements,public.academy_reading_pages,public.academy_read_receipts,public.academy_work from public,anon,authenticated;
grant select on public.academy_lessons,public.academy_requirements,public.academy_reading_pages,public.academy_read_receipts,public.academy_work to authenticated;
create policy lessons_read on public.academy_lessons for select to authenticated using(public.academy_has_access(level) or public.academy_is_admin());
create policy requirements_read on public.academy_requirements for select to authenticated using(public.academy_has_access(level) or public.academy_is_admin());
create policy pages_read on public.academy_reading_pages for select to authenticated using(public.academy_has_access(level) or public.academy_is_admin());
create policy receipts_read on public.academy_read_receipts for select to authenticated using(user_id=auth.uid() or public.academy_is_admin());
create policy work_read on public.academy_work for select to authenticated using(user_id=auth.uid() or public.academy_is_admin());
-- Les écritures passent exclusivement par les fonctions contrôlées.
revoke insert,update,delete on public.academy_progress,public.academy_projects from authenticated;
create or replace function academy_private.learning_lock(p_user uuid,p_level integer) returns void
language sql security definer set search_path='' as $$select pg_advisory_xact_lock(hashtextextended(p_user::text||':'||p_level::text,0));$$;
create or replace function academy_private.step_open(p_user uuid,p_level integer,p_step integer) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.academy_lessons where level=p_level and step=p_step)
 and not exists(select 1 from public.academy_lessons l where l.level=p_level and l.step<p_step and not exists(
 select 1 from public.academy_progress p where p.user_id=p_user and p.level=l.level and p.step=l.step and p.done and p.requirements_version=2));$$;
create or replace function academy_private.invalidate_learning(p_user uuid,p_level integer,p_step integer) returns void
language plpgsql security definer set search_path='' as $$begin
 update public.academy_progress set done=false where user_id=p_user and level=p_level and step>=p_step;
 update public.academy_certificates set revoked=true where user_id=p_user and level=p_level;
end;$$;
create or replace function public.academy_save_notes(p_level integer,p_step integer,p_notes text) returns void
language plpgsql security definer set search_path='' as $$declare previous text;begin
 perform academy_private.learning_lock(auth.uid(),p_level);
 if not public.academy_has_access(p_level) or not academy_private.step_open(auth.uid(),p_level,p_step) then raise exception 'Étape non autorisée';end if;
 if p_notes is null or length(p_notes)>20000 then raise exception 'Carnet invalide';end if;
 select notes into previous from public.academy_progress where user_id=auth.uid() and level=p_level and step=p_step;
 if previous is distinct from p_notes then perform academy_private.invalidate_learning(auth.uid(),p_level,p_step);end if;
 insert into public.academy_progress(user_id,level,step,notes,done,requirements_version) values(auth.uid(),p_level,p_step,p_notes,false,2)
 on conflict(user_id,level,step) do update set notes=excluded.notes,updated_at=now();
end;$$;
create or replace function public.academy_acknowledge_page(p_level integer,p_page integer) returns void
language plpgsql security definer set search_path='' as $$declare s integer;begin
 perform academy_private.learning_lock(auth.uid(),p_level);
 select step into s from public.academy_reading_pages where level=p_level and page=p_page;
 if s is null or not public.academy_has_access(p_level) or not academy_private.step_open(auth.uid(),p_level,s) then raise exception 'Page non autorisée';end if;
 insert into public.academy_read_receipts(user_id,level,page) values(auth.uid(),p_level,p_page) on conflict do nothing;
end;$$;
create or replace function public.academy_submit_work(p_requirement text,p_answer text) returns void
language plpgsql security definer set search_path='' as $$declare r public.academy_requirements;previous text;begin
 select * into r from public.academy_requirements where id=p_requirement;
 if r.id is null then raise exception 'Travail inconnu';end if;
 perform academy_private.learning_lock(auth.uid(),r.level);
 if not public.academy_has_access(r.level) or not academy_private.step_open(auth.uid(),r.level,r.step) then raise exception 'Étape non autorisée';end if;
 if p_answer is null or length(trim(p_answer)) not between 120 and 30000 then raise exception 'Remettez un travail de 120 à 30000 caractères';end if;
 select answer into previous from public.academy_work where user_id=auth.uid() and requirement_id=r.id;
 if previous=p_answer then return;end if;
 perform academy_private.invalidate_learning(auth.uid(),r.level,r.step);
 insert into public.academy_work(user_id,requirement_id,answer) values(auth.uid(),r.id,p_answer)
 on conflict(user_id,requirement_id) do update set answer=excluded.answer,state='submitted',feedback='',reviewed_by=null,reviewed_at=null,updated_at=now();
end;$$;
create or replace function public.academy_complete_step(p_level integer,p_step integer) returns void
language plpgsql security definer set search_path='' as $$begin
 perform academy_private.learning_lock(auth.uid(),p_level);
 if not public.academy_has_access(p_level) or not academy_private.step_open(auth.uid(),p_level,p_step) then raise exception 'Étape non autorisée';end if;
 if not exists(select 1 from public.academy_progress where user_id=auth.uid() and level=p_level and step=p_step and length(trim(notes))>=80) then raise exception 'Carnet obligatoire : 80 caractères minimum';end if;
 if exists(select 1 from public.academy_reading_pages p where p.level=p_level and p.step=p_step and not exists(select 1 from public.academy_read_receipts r where r.user_id=auth.uid() and r.level=p.level and r.page=p.page)) then raise exception 'Consultez et confirmez chaque page de cette étape';end if;
 if exists(select 1 from public.academy_requirements r where r.level=p_level and r.step=p_step and not exists(select 1 from public.academy_work w where w.user_id=auth.uid() and w.requirement_id=r.id and w.state in ('submitted','accepted'))) then raise exception 'Tous les travaux sont obligatoires ; corrigez les remises renvoyées';end if;
 update public.academy_progress set done=true,requirements_version=2,updated_at=now() where user_id=auth.uid() and level=p_level and step=p_step;
end;$$;
create or replace function public.academy_prerequisites(p_level integer,p_user uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare u uuid:=coalesce(p_user,auth.uid()); missing_steps integer;missing_pages integer;missing_work integer;unreviewed integer;begin
 if auth.uid() is null or (u<>auth.uid() and not public.academy_is_admin()) then raise exception 'Non autorisé';end if;
 if p_level is null or p_level not between 1 and 4 then raise exception 'Niveau invalide';end if;
 select count(*) into missing_steps from public.academy_lessons l where l.level=p_level and not exists(select 1 from public.academy_progress p where p.user_id=u and p.level=l.level and p.step=l.step and p.done and p.requirements_version=2 and length(trim(p.notes))>=80);
 select count(*) into missing_pages from public.academy_reading_pages p where p.level=p_level and not exists(select 1 from public.academy_read_receipts r where r.user_id=u and r.level=p.level and r.page=p.page);
 select count(*),count(*) filter(where w.state is distinct from 'accepted') into missing_work,unreviewed from public.academy_requirements r left join public.academy_work w on w.requirement_id=r.id and w.user_id=u where r.level=p_level and (w.state is null or w.state='revision');
 select count(*) into unreviewed from public.academy_requirements r left join public.academy_work w on w.requirement_id=r.id and w.user_id=u where r.level=p_level and w.state is distinct from 'accepted';
 return jsonb_build_object('missing_steps',missing_steps,'missing_pages',missing_pages,'missing_work',missing_work,'unreviewed',unreviewed,'ready',missing_steps=0 and missing_pages=0 and missing_work=0,'ready_grade',missing_steps=0 and missing_pages=0 and missing_work=0 and unreviewed=0);
end;$$;
create or replace function public.academy_submit_project(p_level integer,p_submission text) returns void
language plpgsql security definer set search_path='' as $$declare previous text;begin
 perform academy_private.learning_lock(auth.uid(),p_level);
 if not public.academy_has_access(p_level) or not (public.academy_prerequisites(p_level)->>'ready')::boolean then raise exception 'Terminez toutes les lectures, carnets et remises avant le projet final';end if;
 if p_submission is null or length(trim(p_submission)) not between 200 and 30000 then raise exception 'Dossier final : 200 à 30000 caractères';end if;
 select submission into previous from public.academy_projects where user_id=auth.uid() and level=p_level;
 if previous is distinct from p_submission then
 update public.academy_certificates set revoked=true where user_id=auth.uid() and level=p_level;
 end if;
 insert into public.academy_projects(user_id,level,submission) values(auth.uid(),p_level,p_submission)
 on conflict(user_id,level) do update set submission=excluded.submission,updated_at=now();
end;$$;
create or replace function public.academy_review_work(p_user uuid,p_requirement text,p_state text,p_feedback text,p_expected_updated timestamptz) returns void
language plpgsql security definer set search_path='' as $$declare r public.academy_requirements;begin
 if not public.academy_is_admin() then raise exception 'Formateur requis';end if;
 if p_state not in ('accepted','revision') or p_state is null or p_feedback is null or length(trim(p_feedback)) not between 10 and 5000 then raise exception 'Décision ou retour invalide';end if;
 select * into r from public.academy_requirements where id=p_requirement;
 perform academy_private.learning_lock(p_user,r.level);
 update public.academy_work set state=p_state,feedback=p_feedback,reviewed_by=auth.uid(),reviewed_at=now(),updated_at=clock_timestamp() where user_id=p_user and requirement_id=p_requirement and updated_at=p_expected_updated;
 if not found then raise exception 'Travail modifié ou absent : rechargez avant de corriger';end if;
 if p_state='revision' then perform academy_private.invalidate_learning(p_user,r.level,r.step);end if;
 insert into academy_private.audit(actor,action,details) values(auth.uid(),'review_work',jsonb_build_object('user',p_user,'requirement',p_requirement,'state',p_state));
end;$$;
-- Un refus restrictif complète les éventuelles autres politiques de ce bucket.
create policy academy_no_original_downloads on storage.objects as restrictive for select to anon,authenticated using(
 bucket_id<>'academy-private' or name ~ '^n[1-4]/(course[.]json|pages/[0-9]{3}[.](webp|txt))$');
update storage.buckets set public=false where id='academy-private';

insert into public.academy_lessons select * from json_populate_recordset(null::public.academy_lessons,$catalog$[{"level": 1, "step": 1, "title": "Découvrir l’IA générative", "first_page": 1, "last_page": 8}, {"level": 1, "step": 2, "title": "Lexique et mécanismes", "first_page": 9, "last_page": 13}, {"level": 1, "step": 3, "title": "Histoire, limites et enjeux", "first_page": 14, "last_page": 17}, {"level": 1, "step": 4, "title": "Structurer un prompt", "first_page": 18, "last_page": 20}, {"level": 1, "step": 5, "title": "Ateliers guidés", "first_page": 21, "last_page": 23}, {"level": 1, "step": 6, "title": "Études de cas et modèles", "first_page": 24, "last_page": 27}, {"level": 1, "step": 7, "title": "Évaluation et projet", "first_page": 28, "last_page": 36}, {"level": 1, "step": 8, "title": "Ressources et suite du parcours", "first_page": 37, "last_page": 42}, {"level": 2, "step": 1, "title": "Objectifs et prérequis", "first_page": 1, "last_page": 4}, {"level": 2, "step": 2, "title": "Apprendre par exemples : few-shot", "first_page": 5, "last_page": 8}, {"level": 2, "step": 3, "title": "Décomposer une tâche", "first_page": 9, "last_page": 11}, {"level": 2, "step": 4, "title": "Construire un workflow", "first_page": 12, "last_page": 16}, {"level": 2, "step": 5, "title": "Évaluer et fiabiliser les sorties", "first_page": 17, "last_page": 22}, {"level": 2, "step": 6, "title": "Introduction au RAG et lexique", "first_page": 23, "last_page": 28}, {"level": 2, "step": 7, "title": "Ateliers guidés", "first_page": 29, "last_page": 32}, {"level": 2, "step": 8, "title": "Études de cas métier", "first_page": 33, "last_page": 37}, {"level": 2, "step": 9, "title": "Bibliothèque de prompts", "first_page": 38, "last_page": 41}, {"level": 2, "step": 10, "title": "Automatiser un processus", "first_page": 42, "last_page": 44}, {"level": 2, "step": 11, "title": "Évaluation et projet", "first_page": 45, "last_page": 54}, {"level": 2, "step": 12, "title": "Ressources et suite du parcours", "first_page": 55, "last_page": 59}, {"level": 3, "step": 1, "title": "Objectifs et architecture des modèles", "first_page": 1, "last_page": 5}, {"level": 3, "step": 2, "title": "Embeddings et recherche vectorielle", "first_page": 6, "last_page": 6}, {"level": 3, "step": 3, "title": "RAG avancé", "first_page": 7, "last_page": 8}, {"level": 3, "step": 4, "title": "Agents et appels d’outils", "first_page": 9, "last_page": 10}, {"level": 3, "step": 5, "title": "Fine-tuning, LoRA et PEFT", "first_page": 11, "last_page": 12}, {"level": 3, "step": 6, "title": "Évaluation, sécurité et lexique", "first_page": 13, "last_page": 16}, {"level": 3, "step": 7, "title": "Ateliers techniques guidés", "first_page": 17, "last_page": 23}, {"level": 3, "step": 8, "title": "Études de cas", "first_page": 24, "last_page": 26}, {"level": 3, "step": 9, "title": "Templates réutilisables", "first_page": 27, "last_page": 28}, {"level": 3, "step": 10, "title": "Évaluation et projet", "first_page": 29, "last_page": 36}, {"level": 3, "step": 11, "title": "Ressources et suite du parcours", "first_page": 37, "last_page": 40}, {"level": 4, "step": 1, "title": "Panorama des usages métier", "first_page": 1, "last_page": 7}, {"level": 4, "step": 2, "title": "Données et confidentialité", "first_page": 8, "last_page": 9}, {"level": 4, "step": 3, "title": "Conduite du changement", "first_page": 10, "last_page": 10}, {"level": 4, "step": 4, "title": "Gouvernance et charte d’usage", "first_page": 11, "last_page": 12}, {"level": 4, "step": 5, "title": "Cadrage de projet et lexique", "first_page": 13, "last_page": 16}, {"level": 4, "step": 6, "title": "Ateliers guidés", "first_page": 17, "last_page": 22}, {"level": 4, "step": 7, "title": "Études de cas sectorielles", "first_page": 23, "last_page": 39}, {"level": 4, "step": 8, "title": "Templates métier", "first_page": 40, "last_page": 47}, {"level": 4, "step": 9, "title": "Évaluation et projet sectoriel", "first_page": 48, "last_page": 55}, {"level": 4, "step": 10, "title": "Ressources et suite du parcours", "first_page": 56, "last_page": 60}]$catalog$);

insert into public.academy_requirements select * from json_populate_recordset(null::public.academy_requirements,$catalog$[{"id": "n1-s1-activite", "level": 1, "step": 1, "kind": "activite", "title": "Découvrir l’IA générative", "page": 4, "instruction": "Comparez deux réponses d’un chatbot à une demande de présentation d’une association locale. Livrable : Un tableau de deux usages et deux limites ; distinguer l’outil du modèle et signaler les faits non vérifiés."}, {"id": "n1-s2-activite", "level": 1, "step": 2, "kind": "activite", "title": "Lexique et mécanismes", "page": 9, "instruction": "Réécrivez une même demande courte et détaillée, puis observez ce qui change sans attribuer toutes les variations à un seul paramètre. Livrable : Un glossaire de six termes et deux essais ; ne pas supposer un nombre fixe de tokens par mot ni une vérité garantie par la température."}, {"id": "n1-s3-activite", "level": 1, "step": 3, "kind": "activite", "title": "Histoire, limites et enjeux", "page": 14, "instruction": "Vérifiez une réponse contenant trois affirmations factuelles avec des sources identifiables. Livrable : Une fiche affirmation/source/conclusion ; séparer fait confirmé, doute et erreur ; aucune donnée sensible utilisée."}, {"id": "n1-s4-activite", "level": 1, "step": 4, "kind": "activite", "title": "Structurer un prompt", "page": 18, "instruction": "Rédigez un prompt pour une annonce de formation en précisant public, tâche, contexte, contraintes et format. Livrable : Le prompt, la réponse et une révision ; au moins cinq critères explicites et un contrôle des faits."}, {"id": "n1-s5-activite", "level": 1, "step": 5, "kind": "activite", "title": "Ateliers guidés", "page": 21, "instruction": "Testez un brouillon de message client puis améliorez sa clarté et son format. Livrable : Deux prompts et deux sorties annotées ; justifier trois corrections avec les critères attendus."}, {"id": "n1-s6-activite", "level": 1, "step": 6, "kind": "activite", "title": "Études de cas et modèles", "page": 24, "instruction": "Choisissez une association, un commerce ou un service et adaptez un modèle de réponse à son besoin. Livrable : Une fiche de cas anonymisée, un prompt réutilisable et un contre-exemple ; les variables doivent être identifiables."}, {"id": "n1-s7-activite", "level": 1, "step": 7, "kind": "activite", "title": "Évaluation et projet", "page": 28, "instruction": "Rassemblez cinq prompts, leurs essais et l’analyse de leurs limites ; demandez au formateur la session d’évaluation de 40 questions. Livrable : Un dossier structuré et une auto-évaluation selon la grille /60 ; la lecture des corrigés ne vaut pas réussite à l’examen."}, {"id": "n1-s8-activite", "level": 1, "step": 8, "kind": "activite", "title": "Ressources et suite du parcours", "page": 37, "instruction": "Choisissez deux ressources du manuel et planifiez trois usages à tester pendant les deux prochaines semaines. Livrable : Un plan daté avec objectifs, sources et critères de progrès ; sélectionner N2 uniquement après examen des prérequis."}, {"id": "n1-exercice-1", "level": 1, "step": 1, "kind": "exercice", "title": "Découverte des LLM", "page": 7, "instruction": "Réalisez « Découverte des LLM » en vous appuyant sur les consignes du manuel à partir de la page 7. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n1-exercice-2", "level": 1, "step": 2, "kind": "exercice", "title": "Quiz lexique", "page": 10, "instruction": "Réalisez « Quiz lexique » en vous appuyant sur les consignes du manuel à partir de la page 10. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n1-exercice-3", "level": 1, "step": 2, "kind": "exercice", "title": "Tokenisation manuelle", "page": 10, "instruction": "Réalisez « Tokenisation manuelle » en vous appuyant sur les consignes du manuel à partir de la page 10. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n1-exercice-4", "level": 1, "step": 2, "kind": "exercice", "title": "Limite de contexte", "page": 12, "instruction": "Réalisez « Limite de contexte » en vous appuyant sur les consignes du manuel à partir de la page 12. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n1-exercice-5", "level": 1, "step": 2, "kind": "exercice", "title": "Test de température", "page": 13, "instruction": "Réalisez « Test de température » en vous appuyant sur les consignes du manuel à partir de la page 13. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n1-exercice-6", "level": 1, "step": 3, "kind": "exercice", "title": "Débat éthique", "page": 16, "instruction": "Réalisez « Débat éthique » en vous appuyant sur les consignes du manuel à partir de la page 16. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n1-exercice-7", "level": 1, "step": 4, "kind": "exercice", "title": "Transformation de prompts", "page": 19, "instruction": "Réalisez « Transformation de prompts » en vous appuyant sur les consignes du manuel à partir de la page 19. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n1-exercice-8", "level": 1, "step": 4, "kind": "exercice", "title": "Création de prompts", "page": 20, "instruction": "Réalisez « Création de prompts » en vous appuyant sur les consignes du manuel à partir de la page 20. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n1-atelier-9", "level": 1, "step": 5, "kind": "atelier", "title": "Premiers pas avec un chatbot", "page": 21, "instruction": "Réalisez « Premiers pas avec un chatbot » en vous appuyant sur les consignes du manuel à partir de la page 21. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n1-atelier-10", "level": 1, "step": 5, "kind": "atelier", "title": "Détection des hallucinations", "page": 22, "instruction": "Réalisez « Détection des hallucinations » en vous appuyant sur les consignes du manuel à partir de la page 22. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n1-atelier-11", "level": 1, "step": 5, "kind": "atelier", "title": "Génération de texte", "page": 23, "instruction": "Réalisez « Génération de texte » en vous appuyant sur les consignes du manuel à partir de la page 23. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n1-atelier-12", "level": 1, "step": 5, "kind": "atelier", "title": "Génération d’images — complément annoncé au sommaire", "page": 23, "instruction": "Complément au sommaire : créez deux variantes d’une image pour une association locale. Décrivez les prompts, comparez cadrage et lisibilité, expliquez les limites et les droits des éléments utilisés."}, {"id": "n1-cas-13", "level": 1, "step": 6, "kind": "cas", "title": "Service client : traiter trois demandes", "page": 24, "instruction": "Réalisez « Service client : traiter trois demandes » en vous appuyant sur les consignes du manuel à partir de la page 24. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n1-cas-14", "level": 1, "step": 6, "kind": "cas", "title": "Note de synthèse", "page": 25, "instruction": "Réalisez « Note de synthèse » en vous appuyant sur les consignes du manuel à partir de la page 25. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n1-cas-15", "level": 1, "step": 6, "kind": "cas", "title": "Brainstorming produit — complément annoncé au sommaire", "page": 27, "instruction": "Complément au sommaire : proposez cinq idées de produit utiles localement, comparez faisabilité et public cible, retenez une idée et justifiez votre choix. Présentez les prompts et votre vérification critique."}, {"id": "n1-fil_rouge-16", "level": 1, "step": 7, "kind": "fil_rouge", "title": "Projet fil rouge N1", "page": 31, "instruction": "Réalisez « Projet fil rouge N1 » en vous appuyant sur les consignes du manuel à partir de la page 31. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n2-s1-activite", "level": 2, "step": 1, "kind": "activite", "title": "Objectifs et prérequis", "page": 4, "instruction": "Analysez une tâche répétitive de votre activité et expliquez comment vous la réalisez aujourd’hui. Livrable : Une fiche processus, fréquence, difficultés et résultat attendu ; distinguer observation et estimation."}, {"id": "n2-s2-activite", "level": 2, "step": 2, "kind": "activite", "title": "Apprendre par exemples : few-shot", "page": 5, "instruction": "Créez trois exemples d’entrée-sortie pour classer des demandes clients, puis testez un cas absent des exemples. Livrable : Trois exemples et un jeu de cinq tests ; inclure une catégorie ambiguë et documenter une erreur."}, {"id": "n2-s3-activite", "level": 2, "step": 3, "kind": "activite", "title": "Décomposer une tâche", "page": 9, "instruction": "Découpez la préparation d’un compte rendu en extraction, synthèse et contrôle, sans demander une pensée interne. Livrable : Trois sous-consignes avec entrées et sorties ; une justification concise et vérifiable suffit."}, {"id": "n2-s4-activite", "level": 2, "step": 4, "kind": "activite", "title": "Construire un workflow", "page": 12, "instruction": "Concevez un flux brouillon → vérification → mise en forme pour une note professionnelle. Livrable : Un schéma et trois prompts ; prévoir le rejet d’une entrée incomplète et une validation humaine."}, {"id": "n2-s5-activite", "level": 2, "step": 5, "kind": "activite", "title": "Évaluer et fiabiliser les sorties", "page": 17, "instruction": "Définissez un jeu de dix demandes et comparez deux prompts avec la même grille. Livrable : Un tableau de résultats ; exactitude, complétude et format sont évalués séparément."}, {"id": "n2-s6-activite", "level": 2, "step": 6, "kind": "activite", "title": "Introduction au RAG et lexique", "page": 23, "instruction": "Préparez trois extraits documentaires et demandez une réponse limitée à ces extraits. Livrable : Question, extraits et réponse citée ; signaler l’absence de réponse quand la source manque."}, {"id": "n2-s7-activite", "level": 2, "step": 7, "kind": "activite", "title": "Ateliers guidés", "page": 29, "instruction": "Construisez un assistant de rédaction à partir d’un brief anonymisé et de deux exemples. Livrable : Un prompt système, trois essais et une grille ; éviter d’inclure des données personnelles."}, {"id": "n2-s8-activite", "level": 2, "step": 8, "kind": "activite", "title": "Études de cas métier", "page": 33, "instruction": "Choisissez RH, finance ou service client et repérez les décisions exigeant une intervention humaine. Livrable : Une fiche de cas et un workflow ; aucune décision sensible entièrement déléguée au modèle."}, {"id": "n2-s9-activite", "level": 2, "step": 9, "kind": "activite", "title": "Bibliothèque de prompts", "page": 38, "instruction": "Classez cinq prompts par usage, version et données nécessaires. Livrable : Cinq fiches avec variables, contraintes, exemple de sortie et test de non-régression."}, {"id": "n2-s10-activite", "level": 2, "step": 10, "kind": "activite", "title": "Automatiser un processus", "page": 42, "instruction": "Décrivez un déclencheur, les transformations, la validation et la sortie d’un processus. Livrable : Un protocole de test avec cas normal, donnée absente et erreur ; aucune action externe sans validation prévue."}, {"id": "n2-s11-activite", "level": 2, "step": 11, "kind": "activite", "title": "Évaluation et projet", "page": 45, "instruction": "Remettez le processus initial, cinq prompts, les résultats mesurés et les risques ; préparez le QCM de 30 questions. Livrable : Dossier évalué sur 70 ; calculs reproductibles, limites et données de comparaison explicites."}, {"id": "n2-s12-activite", "level": 2, "step": 12, "kind": "activite", "title": "Ressources et suite du parcours", "page": 55, "instruction": "Choisissez deux routines et une fréquence de révision des prompts. Livrable : Un plan de maintenance et un journal d’essais ; définir quand arrêter une automatisation défaillante."}, {"id": "n2-exercice-1", "level": 2, "step": 2, "kind": "exercice", "title": "Zero-shot vers few-shot", "page": 6, "instruction": "Réalisez « Zero-shot vers few-shot » en vous appuyant sur les consignes du manuel à partir de la page 6. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n2-exercice-2", "level": 2, "step": 2, "kind": "exercice", "title": "Créer des prompts few-shot", "page": 6, "instruction": "Réalisez « Créer des prompts few-shot » en vous appuyant sur les consignes du manuel à partir de la page 6. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n2-exercice-3", "level": 2, "step": 3, "kind": "exercice", "title": "Décomposer et vérifier une résolution — exercice 2.3", "page": 10, "instruction": "Réalisez « Décomposer et vérifier une résolution — exercice 2.3 » en vous appuyant sur les consignes du manuel à partir de la page 10. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne. Demandez des étapes de résolution vérifiables et des justifications synthétiques ; ne demandez pas une pensée interne cachée."}, {"id": "n2-exercice-4", "level": 2, "step": 4, "kind": "exercice", "title": "Décomposer une tâche complexe", "page": 14, "instruction": "Réalisez « Décomposer une tâche complexe » en vous appuyant sur les consignes du manuel à partir de la page 14. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n2-exercice-5", "level": 2, "step": 5, "kind": "exercice", "title": "Audit de réponses générées", "page": 18, "instruction": "Réalisez « Audit de réponses générées » en vous appuyant sur les consignes du manuel à partir de la page 18. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n2-exercice-6", "level": 2, "step": 5, "kind": "exercice", "title": "Détection et correction des biais", "page": 19, "instruction": "Réalisez « Détection et correction des biais » en vous appuyant sur les consignes du manuel à partir de la page 19. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n2-exercice-7", "level": 2, "step": 5, "kind": "exercice", "title": "Audit de sécurité — exercice 2.7", "page": 21, "instruction": "Réalisez « Audit de sécurité — exercice 2.7 » en vous appuyant sur les consignes du manuel à partir de la page 21. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n2-exercice-8", "level": 2, "step": 6, "kind": "exercice", "title": "Pipeline RAG simple — second exercice 2.7", "page": 24, "instruction": "Réalisez « Pipeline RAG simple — second exercice 2.7 » en vous appuyant sur les consignes du manuel à partir de la page 24. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n2-exercice-9", "level": 2, "step": 9, "kind": "exercice", "title": "Templates personnalisés", "page": 40, "instruction": "Réalisez « Templates personnalisés » en vous appuyant sur les consignes du manuel à partir de la page 40. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n2-exercice-10", "level": 2, "step": 10, "kind": "exercice", "title": "Automatisation d’un processus personnel", "page": 43, "instruction": "Réalisez « Automatisation d’un processus personnel » en vous appuyant sur les consignes du manuel à partir de la page 43. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n2-atelier-11", "level": 2, "step": 7, "kind": "atelier", "title": "Prompt vague vers prompt structuré", "page": 29, "instruction": "Réalisez « Prompt vague vers prompt structuré » en vous appuyant sur les consignes du manuel à partir de la page 29. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n2-atelier-12", "level": 2, "step": 7, "kind": "atelier", "title": "Few-shot avec exemples", "page": 30, "instruction": "Réalisez « Few-shot avec exemples » en vous appuyant sur les consignes du manuel à partir de la page 30. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n2-atelier-13", "level": 2, "step": 7, "kind": "atelier", "title": "Chaînage de cinq prompts", "page": 30, "instruction": "Réalisez « Chaînage de cinq prompts » en vous appuyant sur les consignes du manuel à partir de la page 30. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n2-atelier-14", "level": 2, "step": 7, "kind": "atelier", "title": "Évaluation et grille de test", "page": 31, "instruction": "Réalisez « Évaluation et grille de test » en vous appuyant sur les consignes du manuel à partir de la page 31. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n2-cas-15", "level": 2, "step": 8, "kind": "cas", "title": "Compte rendu de réunion", "page": 33, "instruction": "Réalisez « Compte rendu de réunion » en vous appuyant sur les consignes du manuel à partir de la page 33. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n2-cas-16", "level": 2, "step": 8, "kind": "cas", "title": "Proposition commerciale", "page": 34, "instruction": "Réalisez « Proposition commerciale » en vous appuyant sur les consignes du manuel à partir de la page 34. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n2-cas-17", "level": 2, "step": 8, "kind": "cas", "title": "Support interne à partir d’une FAQ", "page": 36, "instruction": "Réalisez « Support interne à partir d’une FAQ » en vous appuyant sur les consignes du manuel à partir de la page 36. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n2-fil_rouge-18", "level": 2, "step": 11, "kind": "fil_rouge", "title": "Transformation d’un processus métier réel", "page": 49, "instruction": "Réalisez « Transformation d’un processus métier réel » en vous appuyant sur les consignes du manuel à partir de la page 49. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n3-s1-activite", "level": 3, "step": 1, "kind": "activite", "title": "Objectifs et architecture des modèles", "page": 4, "instruction": "Dessinez un système qui sépare interface, modèle, outils, données et journalisation. Livrable : Un diagramme avec flux et frontières de confiance ; distinguer modèle entraîné et données consultées."}, {"id": "n3-s2-activite", "level": 3, "step": 2, "kind": "activite", "title": "Embeddings et recherche vectorielle", "page": 6, "instruction": "Définissez dix requêtes et les passages attendus sur un petit corpus autorisé. Livrable : Un jeu de pertinence et un indicateur de rappel ; documenter les requêtes sans réponse."}, {"id": "n3-s3-activite", "level": 3, "step": 3, "kind": "activite", "title": "RAG avancé", "page": 7, "instruction": "Comparez deux découpages du même corpus en conservant modèle et questions identiques. Livrable : Résultats sourcés, coût et latence observés ; isoler les erreurs de recherche des erreurs de génération."}, {"id": "n3-s4-activite", "level": 3, "step": 4, "kind": "activite", "title": "Agents et appels d’outils", "page": 9, "instruction": "Concevez un outil de consultation et un outil d’action avec validation explicite. Livrable : Schéma d’autorisations et trois tests ; refuser arguments invalides et action non autorisée."}, {"id": "n3-s5-activite", "level": 3, "step": 5, "kind": "activite", "title": "Fine-tuning, LoRA et PEFT", "page": 11, "instruction": "Analysez une tâche de style et une tâche de connaissance documentaire ; proposez la méthode adaptée. Livrable : Une décision argumentée avec données, coûts, métriques et limites ; prévoir un jeu de validation indépendant."}, {"id": "n3-s6-activite", "level": 3, "step": 6, "kind": "activite", "title": "Évaluation, sécurité et lexique", "page": 13, "instruction": "Écrivez cinq entrées adverses, dont une instruction hostile dans un document fourni. Livrable : Un tableau entrée/résultat attendu/résultat observé ; aucune donnée ou clé sensible dans les journaux."}, {"id": "n3-s7-activite", "level": 3, "step": 7, "kind": "activite", "title": "Ateliers techniques guidés", "page": 17, "instruction": "Implémentez le pipeline du manuel dans un environnement isolé avec un petit corpus non sensible. Livrable : Code, dépendances, configuration d’exemple sans secret et tests ; documenter une exécution reproductible."}, {"id": "n3-s8-activite", "level": 3, "step": 8, "kind": "activite", "title": "Études de cas", "page": 24, "instruction": "Comparez un support client documentaire et un assistant d’analyse de documents. Livrable : Deux fiches d’architecture ; préciser responsabilités, critères de succès et cas de refus."}, {"id": "n3-s9-activite", "level": 3, "step": 9, "kind": "activite", "title": "Templates réutilisables", "page": 27, "instruction": "Définissez un schéma de réponse et un prompt d’évaluation réutilisable. Livrable : Un schéma validable, exemples valides/invalides et tests ; rejeter les champs inattendus."}, {"id": "n3-s10-activite", "level": 3, "step": 10, "kind": "activite", "title": "Évaluation et projet", "page": 29, "instruction": "Remettez code, corpus autorisé, évaluations, garde-fous et documentation ; préparez l’évaluation de 40 items. Livrable : Projet /70 et QCM ramené à /30 dans le total ; distinguer résultats mesurés et limites connues."}, {"id": "n3-s11-activite", "level": 3, "step": 11, "kind": "activite", "title": "Ressources et suite du parcours", "page": 37, "instruction": "Établissez un plan de suivi des erreurs, coûts et changements de version. Livrable : Un plan avec seuils d’alerte, responsable et procédure de retour à la version précédente."}, {"id": "n3-atelier-1", "level": 3, "step": 7, "kind": "atelier", "title": "Pipeline RAG minimal", "page": 17, "instruction": "Réalisez « Pipeline RAG minimal » en vous appuyant sur les consignes du manuel à partir de la page 17. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n3-atelier-2", "level": 3, "step": 7, "kind": "atelier", "title": "Améliorer le retrieval", "page": 19, "instruction": "Réalisez « Améliorer le retrieval » en vous appuyant sur les consignes du manuel à partir de la page 19. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n3-atelier-3", "level": 3, "step": 7, "kind": "atelier", "title": "Agent avec appels d’outils", "page": 20, "instruction": "Réalisez « Agent avec appels d’outils » en vous appuyant sur les consignes du manuel à partir de la page 20. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n3-atelier-4", "level": 3, "step": 7, "kind": "atelier", "title": "Fine-tuning LoRA", "page": 21, "instruction": "Réalisez « Fine-tuning LoRA » en vous appuyant sur les consignes du manuel à partir de la page 21. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n3-atelier-5", "level": 3, "step": 7, "kind": "atelier", "title": "Évaluation automatisée et garde-fous", "page": 23, "instruction": "Réalisez « Évaluation automatisée et garde-fous » en vous appuyant sur les consignes du manuel à partir de la page 23. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n3-cas-6", "level": 3, "step": 8, "kind": "cas", "title": "Support client documentaire", "page": 24, "instruction": "Réalisez « Support client documentaire » en vous appuyant sur les consignes du manuel à partir de la page 24. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n3-cas-7", "level": 3, "step": 8, "kind": "cas", "title": "Analyse de documents financiers", "page": 25, "instruction": "Réalisez « Analyse de documents financiers » en vous appuyant sur les consignes du manuel à partir de la page 25. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n3-cas-8", "level": 3, "step": 8, "kind": "cas", "title": "Rapports au format maison", "page": 26, "instruction": "Réalisez « Rapports au format maison » en vous appuyant sur les consignes du manuel à partir de la page 26. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n3-fil_rouge-9", "level": 3, "step": 10, "kind": "fil_rouge", "title": "Assistant métier complet", "page": 32, "instruction": "Réalisez « Assistant métier complet » en vous appuyant sur les consignes du manuel à partir de la page 32. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n4-s1-activite", "level": 4, "step": 1, "kind": "activite", "title": "Panorama des usages métier", "page": 4, "instruction": "Listez cinq usages dans votre métier et comparez valeur attendue, faisabilité et risques. Livrable : Une matrice et un usage prioritaire ; justifier le choix sans inventer de gain chiffré."}, {"id": "n4-s2-activite", "level": 4, "step": 2, "kind": "activite", "title": "Données et confidentialité", "page": 8, "instruction": "Listez les données nécessaires puis préparez un jeu fictif ou anonymisé. Livrable : Une cartographie des données et accès ; exclure les informations inutiles et prévoir la conservation."}, {"id": "n4-s3-activite", "level": 4, "step": 3, "kind": "activite", "title": "Conduite du changement", "page": 10, "instruction": "Identifiez utilisateurs, responsables et objections pour un pilote limité. Livrable : Un plan d’accompagnement avec formation, support et retour d’expérience."}, {"id": "n4-s4-activite", "level": 4, "step": 4, "kind": "activite", "title": "Gouvernance et charte d’usage", "page": 11, "instruction": "Rédigez une charte pour une équipe de votre secteur. Livrable : Règles autorisées/interdites, validation humaine et signalement ; préciser qui décide et qui contrôle."}, {"id": "n4-s5-activite", "level": 4, "step": 5, "kind": "activite", "title": "Cadrage de projet et lexique", "page": 13, "instruction": "Décrivez besoin, périmètre, livrables, contraintes et critères d’arrêt. Livrable : Une fiche projet approuvable ; distinguer résultat attendu et moyens envisagés."}, {"id": "n4-s6-activite", "level": 4, "step": 6, "kind": "activite", "title": "Ateliers guidés", "page": 17, "instruction": "Rédigez trois prompts complémentaires et testez-les sur des données fictives. Livrable : Un kit, trois essais et corrections ; vérifier contenu, format et risques avant diffusion."}, {"id": "n4-s7-activite", "level": 4, "step": 7, "kind": "activite", "title": "Études de cas sectorielles", "page": 23, "instruction": "Choisissez un cas du manuel et adaptez-le à votre organisation. Livrable : Une analyse du contexte, des acteurs et des contraintes ; expliquer les adaptations nécessaires."}, {"id": "n4-s8-activite", "level": 4, "step": 8, "kind": "activite", "title": "Templates métier", "page": 40, "instruction": "Personnalisez fiche de cadrage, charte et compte rendu de test. Livrable : Trois documents cohérents ; noms des responsables, critères et circuit de validation explicites."}, {"id": "n4-s9-activite", "level": 4, "step": 9, "kind": "activite", "title": "Évaluation et projet sectoriel", "page": 48, "instruction": "Remettez cas d’usage, kit de prompts, risques et plan de déploiement ; préparez le QCM de 30 items. Livrable : Projet /70 et soutenance ; justifier les choix et présenter les limites sans promettre une conformité juridique automatique."}, {"id": "n4-s10-activite", "level": 4, "step": 10, "kind": "activite", "title": "Ressources et suite du parcours", "page": 56, "instruction": "Définissez les indicateurs et revues après le pilote. Livrable : Un calendrier, un responsable et trois critères de décision pour poursuivre, corriger ou arrêter."}, {"id": "n4-cas-1", "level": 4, "step": 5, "kind": "cas", "title": "Cadrage d’un projet RAG", "page": 13, "instruction": "Réalisez « Cadrage d’un projet RAG » en vous appuyant sur les consignes du manuel à partir de la page 13. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n4-atelier-2", "level": 4, "step": 6, "kind": "atelier", "title": "Cartographie des usages", "page": 17, "instruction": "Réalisez « Cartographie des usages » en vous appuyant sur les consignes du manuel à partir de la page 17. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n4-atelier-3", "level": 4, "step": 6, "kind": "atelier", "title": "Charte d’usage IA", "page": 19, "instruction": "Réalisez « Charte d’usage IA » en vous appuyant sur les consignes du manuel à partir de la page 19. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n4-atelier-4", "level": 4, "step": 6, "kind": "atelier", "title": "Cadrage d’un projet IA", "page": 20, "instruction": "Réalisez « Cadrage d’un projet IA » en vous appuyant sur les consignes du manuel à partir de la page 20. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne."}, {"id": "n4-atelier-5", "level": 4, "step": 6, "kind": "atelier", "title": "Conduite du changement", "page": 22, "instruction": "Réalisez « Conduite du changement » en vous appuyant sur les consignes du manuel à partir de la page 22. Remettez votre démarche, votre production, les tests réalisés, leurs résulta